    <style>
        :root{--forest:#104b3b;--forest2:#0c392f;--green:#26845d;--lime:#b6dd68;--ink:#1a352f;--muted:#6b7d77;--paper:#faf9f4;--line:#e5e9e2;--blue:#e7f3f5;--mint:#e9f3e9;--cream:#fff1dc;--shadow:0 24px 70px #143b2d12}
        *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif}button,input{font:inherit}button{cursor:pointer}.wrap{width:min(1160px,calc(100% - 48px));margin:auto}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;color:var(--forest);font:800 16px Manrope,sans-serif;letter-spacing:-.4px}.brandmark{width:40px;height:40px;border-radius:13px;background:var(--forest);display:grid;place-items:center;color:#d5ef8e;font-size:21px}.topnav{display:flex;align-items:center;gap:30px}.topnav a{font-size:13px;font-weight:700;color:#62746d;text-decoration:none}.btn{border:0;border-radius:9px;padding:12px 18px;background:var(--forest);color:#fff;font-weight:700;font-size:13px;transition:.2s}.btn:hover{background:var(--forest2);transform:translateY(-1px)}.btn.light{background:#fff;color:var(--forest);border:1px solid var(--line)}.hero{padding:70px 0 58px;display:grid;grid-template-columns:1.14fr .86fr;align-items:center;gap:54px}.eyebrow{display:flex;align-items:center;gap:9px;color:var(--green);font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase}.eyebrow:before{content:'';width:23px;height:2px;background:var(--lime)}h1,h2,h3,p{margin-top:0}h1{font:800 clamp(39px,5vw,62px)/1.04 Manrope,sans-serif;letter-spacing:-2.7px;color:var(--forest);margin:18px 0 18px;max-width:630px}h1 em{font-style:normal;color:#79a942}.hero-copy{max-width:520px;color:#6b7d77;font-size:16px;line-height:1.7}.hero-actions{display:flex;gap:12px;margin-top:26px}.micro{display:flex;align-items:center;gap:8px;color:#77867e;font-size:11px;margin-top:17px}.micro span{color:#7dab45;font-size:17px}.hero-art{position:relative;min-height:350px;border-radius:30px;background:#e8f2e8;overflow:hidden;display:grid;place-items:center}.sun{position:absolute;width:242px;height:242px;right:39px;top:20px;border-radius:50%;background:#c3e283}.house{position:relative;width:79%;height:250px;margin-top:58px;border-radius:17px 17px 7px 7px;background:#f4e7cb;box-shadow:0 18px 25px #30482a17}.roof{position:absolute;top:-80px;left:-6%;width:112%;height:115px;background:#bb7650;clip-path:polygon(50% 0,100% 100%,0 100%)}.roof:after{content:'';position:absolute;inset:15px 18px 0;background:#d59062;clip-path:polygon(50% 0,100% 100%,0 100%)}.house-front{position:absolute;inset:0;background:linear-gradient(90deg,#f6ebd5 0 56%,#eddbba 56%)}.window{position:absolute;width:56px;height:68px;top:56px;left:26px;background:#95c5c0;border:7px solid #fff8e9;border-radius:5px;box-shadow:inset 0 0 0 2px #d8e9db}.window.two{left:auto;right:25px}.door{position:absolute;bottom:0;left:calc(56% - 28px);width:58px;height:108px;background:#927057;border-radius:7px 7px 0 0}.door:after{content:'';position:absolute;right:8px;top:52px;width:5px;height:5px;background:#eed58c;border-radius:50%}.house-label{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);width:max-content;padding:12px 17px;border-radius:12px;background:#fff;color:var(--forest);font-size:11px;font-weight:800;box-shadow:var(--shadow)}.bubble{position:absolute;top:34px;left:28px;background:#fff;padding:11px 15px;border-radius:12px 12px 12px 3px;color:var(--forest);font-size:12px;font-weight:700;box-shadow:var(--shadow)}.bubble.right{top:auto;left:auto;right:20px;bottom:51px;border-radius:12px 12px 3px 12px;background:#eff5d9}.section{padding:63px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:28px}.section-head h2{font:800 32px/1.12 Manrope,sans-serif;letter-spacing:-1.2px;color:var(--forest);margin:12px 0 0}.section-head p{max-width:440px;color:var(--muted);font-size:13px;line-height:1.65;margin:0}.cases{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.case-card{background:white;border:1px solid var(--line);border-radius:17px;padding:20px;min-height:232px;transition:.22s;box-shadow:0 5px 18px #173f3010}.case-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:#bed798}.case-no{width:35px;height:35px;border-radius:11px;background:var(--mint);color:var(--green);display:grid;place-items:center;font-weight:800;font-size:13px}.case-card h3{font:800 16px/1.35 Manrope,sans-serif;color:var(--forest);margin:17px 0 8px}.case-card p{font-size:12px;line-height:1.6;color:var(--muted);margin:0}.case-link{margin-top:17px;font-size:11px;font-weight:800;color:var(--green)}.how{background:#f0f4ec}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:34px}.step{display:flex;gap:15px}.step-no{flex:none;width:37px;height:37px;border:1px solid #bed798;border-radius:50%;display:grid;place-items:center;color:var(--green);font-weight:800}.step h3{font:700 14px Manrope,sans-serif;color:var(--forest);margin:4px 0 6px}.step p{font-size:12px;line-height:1.6;color:var(--muted);margin:0}.offices{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:29px}.office{background:white;border:1px solid var(--line);border-radius:13px;padding:17px}.office strong{display:block;color:var(--forest);font:800 13px Manrope,sans-serif;margin-bottom:6px}.office span{font-size:11px;line-height:1.6;color:var(--muted)}.notice{border-left:3px solid #d39a42;background:var(--cream);padding:13px 16px;color:#775d32;font-size:11px;line-height:1.6;margin-top:20px;border-radius:0 8px 8px 0}.footer{border-top:1px solid var(--line);padding:24px 0;color:#829088;font-size:11px}.footer-inner{display:flex;justify-content:space-between}.chat-fab{position:fixed;right:27px;bottom:25px;z-index:8;display:flex;align-items:center;gap:10px;padding:13px 17px;border:0;border-radius:16px;background:var(--forest);color:white;font-size:12px;font-weight:800;box-shadow:0 12px 30px #123d2d42}.chat-fab .chat-icon{font-size:20px}.overlay{position:fixed;inset:0;z-index:10;background:#102d2470;display:none;align-items:center;justify-content:center;padding:18px}.overlay.open{display:flex}.modal{position:relative;width:min(465px,100%);padding:30px;background:white;border-radius:21px;box-shadow:0 30px 80px #102d2440}.modal h2{font:800 25px Manrope;color:var(--forest);margin:0 0 8px}.modal>p{font-size:12px;color:var(--muted);line-height:1.6;margin-bottom:20px}.close{position:absolute;right:17px;top:14px;border:0;background:none;font-size:24px;color:#708078}.field{margin:12px 0}.field label{display:block;font-size:11px;font-weight:800;color:var(--forest);margin-bottom:6px}.field input{width:100%;height:43px;border:1px solid #dce3dc;border-radius:9px;padding:0 12px;font-size:13px;outline:none}.field input:focus{border-color:#6aab7b;box-shadow:0 0 0 3px #76b88720}.modal .btn{width:100%;margin-top:8px;height:45px}.form-msg{font-size:12px;line-height:1.5;margin-top:12px;color:#a34433}.form-msg.ok{color:#26845d}.chat-panel{position:fixed;right:25px;bottom:92px;z-index:9;width:min(375px,calc(100vw - 32px));height:520px;max-height:calc(100vh - 120px);background:#fff;border:1px solid var(--line);border-radius:19px;box-shadow:0 25px 70px #102d2430;display:none;overflow:hidden;flex-direction:column}.chat-panel.open{display:flex}.chat-head{display:flex;align-items:center;gap:11px;padding:16px;background:var(--forest);color:white}.bot-avatar{width:38px;height:38px;border-radius:12px;background:#d5ed91;display:grid;place-items:center;color:var(--forest);font-size:19px}.chat-head strong{font:700 13px Manrope;display:block}.chat-head small{font-size:10px;color:#c9ddcf}.chat-head button{margin-left:auto;border:0;color:#fff;background:transparent;font-size:20px}.chat-log{flex:1;padding:15px;overflow-y:auto;background:#fafbf8}.msg{max-width:89%;padding:11px 12px;border-radius:13px;font-size:12px;line-height:1.55;margin:0 0 10px;white-space:pre-line}.msg.bot{background:white;border:1px solid var(--line);border-top-left-radius:3px;color:#40534c}.msg.user{background:#e7f1dd;color:var(--forest);margin-left:auto;border-top-right-radius:3px}.chips{display:flex;flex-direction:column;gap:7px;margin:3px 0 11px}.chip{background:white;border:1px solid #cbdcc7;border-radius:9px;padding:9px 10px;text-align:left;color:var(--forest);font-size:11px;font-weight:700}.chip:hover{background:var(--mint)}.chat-compose{border-top:1px solid var(--line);padding:10px;display:flex;gap:8px}.chat-compose input{flex:1;min-width:0;border:1px solid var(--line);border-radius:9px;padding:10px;font-size:12px}.chat-compose button{width:40px;border:0;border-radius:9px;background:var(--forest);color:#fff;font-weight:800}
        .brochure-page{background:#fff;border:1px solid #dfe8da;border-radius:14px;padding:15px;margin:5px 0 12px;box-shadow:0 5px 16px #183d2810}.brochure-kicker{font-size:9px;font-weight:800;letter-spacing:1px;color:#26845d;text-transform:uppercase;line-height:1.45}.brochure-title{font:800 17px/1.2 Manrope,sans-serif;color:var(--forest);margin:9px 0}.brochure-copy{font-size:11px;line-height:1.55;color:#52675e;white-space:pre-line;margin:0 0 10px}.brochure-note{padding:9px 10px;background:#fff4df;border-radius:8px;color:#765e36;font-size:10px;line-height:1.45}.brochure-ask{width:100%;margin-top:9px;padding:9px;background:#eaf3e8;color:var(--forest);border:0;border-radius:8px;font-size:10px;font-weight:800}.brochure-controls{display:flex;align-items:center;justify-content:space-between;gap:7px;margin-top:13px}.brochure-arrow{padding:7px 9px;border:1px solid #dce6dc;background:#fff;color:var(--forest);border-radius:7px;font-size:10px;font-weight:700}.brochure-arrow:disabled{opacity:.38;cursor:default}.brochure-count{font-size:10px;font-weight:800;color:#60776c}.brochure-dots{display:flex;justify-content:center;gap:6px;margin-top:10px}.brochure-dot{width:7px;height:7px;padding:0;border:0;border-radius:9px;background:#d5ded3}.brochure-dot.active{width:20px;background:#65a25f}
        .brochure-section{border:1px solid #e7ede5;border-radius:8px;margin-top:8px;padding:9px 10px;background:#fff}.brochure-section summary{font-size:11px;font-weight:800;color:var(--forest);cursor:pointer}.brochure-section ul,.brochure-section ol{padding-left:19px;margin:9px 0 2px;color:#586b61;font-size:10px;line-height:1.55}.brochure-checklist{display:grid;gap:8px;margin-top:11px;padding:11px;background:#f4f7f1;border-radius:9px}.brochure-checklist strong{font:700 11px Manrope;color:var(--forest);margin-bottom:2px}.brochure-checklist label{display:flex;align-items:flex-start;gap:7px;color:#52675e;font-size:10px;line-height:1.4}.brochure-checklist input{accent-color:var(--green);margin:1px 0 0;flex:none;width:14px;height:14px}
        @media(max-width:850px){.hero{grid-template-columns:1fr;gap:32px;padding-top:52px}.hero-art{min-height:310px}.cases{grid-template-columns:repeat(2,1fr)}.offices{grid-template-columns:repeat(2,1fr)}.section-head{align-items:start;flex-direction:column}.steps{grid-template-columns:1fr}.topnav{gap:14px}.topnav a:not(.btn){display:none}}
        @media(max-width:520px){.wrap{width:min(100% - 32px,1160px)}.topbar{height:68px}.brand{font-size:13px}.brandmark{width:35px;height:35px}.hero{padding:44px 0}.hero-copy{font-size:14px}h1{letter-spacing:-1.7px}.hero-actions{flex-direction:column;align-items:stretch}.hero-art{min-height:270px}.house{height:190px;width:82%;margin-top:54px}.roof{top:-66px;height:95px}.window{width:45px;height:52px;top:43px}.door{height:82px;width:48px}.section{padding:48px 0}.section-head h2{font-size:27px}.cases{grid-template-columns:1fr 1fr;gap:9px}.case-card{padding:14px;min-height:220px}.case-card h3{font-size:13px}.case-card p{font-size:11px}.offices{gap:8px}.office{padding:13px}.footer-inner{gap:12px;flex-direction:column}.chat-fab{right:15px;bottom:15px}.chat-panel{right:12px;bottom:75px}}
        .case-card p,.office span{font-size:14px}.notice{font-size:13px}.brochure-copy{font-size:13px}.brochure-note{font-size:12px}.brochure-section summary{font-size:13px}.brochure-section ul,.brochure-section ol,.brochure-checklist label{font-size:12px}.brochure-ask,.brochure-arrow{font-size:12px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #a4cb51;outline-offset:3px}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important;animation:none!important}}
    </style>
    <style>
        .satisfaction-survey{margin:10px 0 12px;padding:14px;background:#f2f7ed;border:1px solid #d8e6d1;border-radius:12px;color:#24483b}.satisfaction-survey strong{display:block;font:800 13px Manrope,sans-serif;color:#104b3b}.satisfaction-survey p{font-size:12px;line-height:1.5;margin:7px 0 10px}.satisfaction-profile{display:grid;grid-template-columns:1fr 100px;gap:8px;margin:10px 0}.satisfaction-profile label{display:grid;gap:5px;font-size:10px;font-weight:700;color:#40534c}.satisfaction-profile input{width:100%;height:36px;padding:0 9px;border:1px solid #d6e2d3;border-radius:8px;background:white;font:12px 'DM Sans',sans-serif}.satisfaction-profile .satisfaction-privacy{grid-column:1/-1;font-size:10px;color:#718078;margin:0}.satisfaction-stars{display:flex;gap:5px;margin:6px 0 11px}.satisfaction-star{position:relative;display:inline-flex;align-items:center;justify-content:center;width:37px;height:37px;border:1px solid #d6e2d3;border-radius:9px;background:white;color:#aab5ac;font-size:24px;cursor:pointer}.satisfaction-star input{position:absolute;opacity:0;width:1px;height:1px}.satisfaction-star.selected{color:#e9a92c;background:#fffaf0;border-color:#e8c777}.satisfaction-star:focus-within{outline:3px solid #a4cb51;outline-offset:2px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.satisfaction-submit{border:0;border-radius:8px;padding:9px 12px;background:#104b3b;color:white;font-size:11px;font-weight:800}.satisfaction-submit:disabled{opacity:.45;cursor:default}.satisfaction-status{font-size:11px;color:#a34433;margin-top:7px}.satisfaction-thanks{color:#26845d;font-weight:700;margin:0!important}
    </style>
</head>
<body>
    <header class="wrap topbar">
        <a class="brand" href="#inicio" style="text-decoration:none"><span class="brandmark">⌂</span><span>TRÁMITES MÁS CLAROS<br><small style="font:600 9px 'DM Sans';letter-spacing:1px;color:#789087">PERSONAS MÁS AUTÓNOMAS · HUANCAYO</small></span></a>
        <nav class="topnav"><a href="#casos">Casos</a><a href="#pasos">Cómo funciona</a><a href="#orientacion">Orientación</a><a class="btn light" href="{{ route('login') }}" style="text-decoration:none">Ingresar</a><button class="btn" type="button" onclick="toggleChat(true)">Comenzar consulta</button></nav>
    </header>
    <main>
        <section class="wrap hero" id="inicio">
            <div><div class="eyebrow">Información clara para tu hogar</div><h1>Tu casa también <em>tiene futuro.</em></h1><p class="hero-copy">Una guía sencilla para orientarte en la formalización de tu vivienda. Identifica tu situación y conoce qué documentos preparar y a dónde acudir.</p><div class="hero-actions"><button class="btn" onclick="toggleChat(true)">Encontrar mi trámite&nbsp; →</button><a class="btn light" href="#casos" style="text-decoration:none">Explorar los casos</a></div><div class="micro"><span>✓</span> Orientación gratuita · No reemplaza la confirmación oficial</div></div>
            <div class="hero-art" aria-label="Ilustración de vivienda"><div class="sun"></div><div class="bubble">¿Qué trámite necesitas?</div><div class="house"><div class="roof"></div><div class="house-front"></div><div class="window"></div><div class="window two"></div><div class="door"></div></div><div class="house-label">Tu hogar, paso a paso</div><div class="bubble right">Guía simple para tu familia&nbsp; ✦</div></div>
        </section>
        <section class="section" id="casos"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Primero identifica tu caso</div><h2>¿Cuál se parece a tu situación?</h2></div><p>Cada vivienda puede necesitar una ruta distinta. Elige un caso para recibir orientación sobre los primeros pasos.</p></div>
            <div class="cases">
                <button class="case-card" onclick="selectCase('posesion')" style="text-align:left"><span class="case-no">01</span><h3>Solo tengo posesión del terreno</h3><p>Vives en el terreno, pero todavía no tienes un título de propiedad inscrito.</p><div class="case-link">Consultar este caso&nbsp; →</div></button>
                <button class="case-card" onclick="selectCase('cofopri')" style="text-align:left"><span class="case-no" style="background:#fff1dc;color:#b2762b">02</span><h3>Mi zona está en formalización</h3><p>Tu vivienda pertenece a una zona o programa de formalización de COFOPRI.</p><div class="case-link">Consultar este caso&nbsp; →</div></button>
                <button class="case-card" onclick="selectCase('sunarp')" style="text-align:left"><span class="case-no" style="background:#e7f3f5;color:#26808a">03</span><h3>Tengo documentos, pero no está inscrita</h3><p>Tienes escritura u otros documentos, pero el predio no figura en SUNARP.</p><div class="case-link">Consultar este caso&nbsp; →</div></button>
                <button class="case-card" onclick="selectCase('herencia')" style="text-align:left"><span class="case-no" style="background:#f6e8ef;color:#b45478">04</span><h3>Herencia o reparto familiar</h3><p>Necesitas regularizar o dividir una propiedad heredada o compartida.</p><div class="case-link">Consultar este caso&nbsp; →</div></button>
            </div>
        </div></section>
        <section class="section how" id="pasos"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Una ruta sencilla</div><h2>Avanza con más claridad</h2></div><p>El asistente te ayuda a reconocer tu situación, organizar documentos y ubicar dónde pedir orientación.</p></div>
            <div class="steps"><div class="step"><span class="step-no">1</span><div><h3>Cuéntanos tu situación</h3><p>Selecciona uno de los cuatro casos de vivienda para ver una orientación inicial.</p></div></div><div class="step"><span class="step-no">2</span><div><h3>Prepara tus documentos</h3><p>Revisa la lista orientativa y reúne originales o copias según corresponda.</p></div></div><div class="step"><span class="step-no">3</span><div><h3>Confirma antes de iniciar</h3><p>Consulta requisitos, costos y horarios vigentes con la entidad responsable.</p></div></div></div>
        </div></section>
        <section class="section" id="orientacion"><div class="wrap"><div class="section-head"><div><div class="eyebrow">¿Dónde pedir orientación?</div><h2>Entidades que pueden ayudarte</h2></div><p>La entidad depende del caso. Confirma siempre requisitos, tarifas y horarios directamente con la oficina.</p></div>
            <div class="offices"><div class="office"><strong>Municipalidad Provincial</strong><span>Gerencia de Desarrollo Urbano<br>Calle Real N.° 800, Huancayo<br>Lun–vie · 8:00 a. m.–4:30 p. m.</span></div><div class="office"><strong>COFOPRI · Oficina Zonal Junín</strong><span>Jr. Lima 590–594, Huancayo<br>Formalización en zonas y programas.</span></div><div class="office"><strong>SUNARP · Oficina Registral</strong><span>Jr. Atalaya N.° 1250, El Tambo<br>Inscripción de propiedad y publicidad registral.</span></div><div class="office"><strong>SATH Huancayo</strong><span>Paseo La Breña N.° 539, Huancayo<br>Orientación tributaria municipal.</span></div></div>
            <div class="notice">Esta guía ofrece orientación inicial basada en el tríptico. Requisitos, costos y horarios pueden variar según el caso; confirma la información vigente con la entidad correspondiente.</div>
        </div></section>
    </main>
    <footer class="footer"><div class="wrap footer-inner"><span>Trámites más claros, personas más autónomas · Huancayo, Perú</span><span>Prototipo académico · Equipo 10 · Universidad Continental</span></div></footer>

    <button class="chat-fab" type="button" onclick="toggleChat()"><span class="chat-icon">◉</span> Hablar con el asistente</button>
    <section class="chat-panel" id="chatPanel" aria-label="Asistente y tríptico digital"><div class="chat-head"><span class="bot-avatar">⌂</span><div><strong>Asistente de vivienda</strong><small>Tríptico digital · 6 paneles</small></div><button aria-label="Cerrar chat" onclick="toggleChat()">×</button></div><div class="chat-log" id="chatLog"></div><form class="chat-compose" onsubmit="sendChat(event)"><input id="chatInput" placeholder="Escribe tu consulta…" autocomplete="off"><button aria-label="Enviar">↑</button></form></section>
    <script>
        const chatPanel=document.getElementById('chatPanel');
        const log=document.getElementById('chatLog');
        const csrf=document.querySelector('meta[name="csrf-token"]').content;
        function createUuid(){if(window.crypto&&typeof window.crypto.randomUUID==='function')return window.crypto.randomUUID();const bytes=new Uint8Array(16);if(window.crypto&&typeof window.crypto.getRandomValues==='function')window.crypto.getRandomValues(bytes);else for(let i=0;i<bytes.length;i++)bytes[i]=Math.floor(Math.random()*256);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;return Array.from(bytes,(value,index)=>`${[4,6,8,10].includes(index)?'-':''}${value.toString(16).padStart(2,'0')}`).join('')}
        let sessionKey;try{sessionKey=sessionStorage.getItem('guia_analytics_session')}catch{}sessionKey=sessionKey||createUuid();try{sessionStorage.setItem('guia_analytics_session',sessionKey)}catch{}
        let lastPanelStart=Date.now(), pageStart=Date.now(), exitSent=false, checklistStarted={};
        const analyticsEnabled=@json($trackAnalytics);
        function track(type,caseKey=null,extra={},duration=null){if(!analyticsEnabled)return;try{const payload={event_uuid:createUuid(),session_key:sessionKey,event_type:type,case:caseKey,page:location.pathname+location.hash,duration_seconds:duration,metadata:extra};fetch('{{ route('analytics.event') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(payload),keepalive:true}).catch(()=>{});}catch{}}
        track('session_start');track('page_view');
        function sendExit(){if(exitSent)return;exitSent=true;const activeCase=panels[brochureIndex]?.caseKey||null;track('page_exit',activeCase,{},Math.min(1800,Math.round((Date.now()-(activeCase?lastPanelStart:pageStart))/1000)))}
        document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')sendExit();else{exitSent=false;pageStart=Date.now();lastPanelStart=Date.now()}});
        window.addEventListener('pagehide',sendExit);
        const panels=[
            {kicker:'GUÍA PARA FORMALIZAR TU VIVIENDA',title:'Tu casa también tiene futuro',text:'Una guía sencilla para personas adultas mayores. Primero identifica tu situación y sigue la ruta que corresponde.',note:'Elige un caso y avanza paso a paso.',caseKey:null},
            {kicker:'PASO 1 · IDENTIFICA TU CASO',title:'¿Cuál se parece a tu situación?',text:'A · Solo tengo posesión del terreno.\nVivo en el terreno, pero no tengo título de propiedad inscrito.\n\nB · Mi zona está en formalización.\nMi vivienda pertenece a un proceso de formalización de COFOPRI.\n\nC · Tengo documentos, pero no está inscrita.\nTengo escritura u otro documento, pero el predio no figura en SUNARP.\n\nD · Herencia o reparto familiar.\nQuiero regularizar o dividir una propiedad familiar.',note:'Toca un caso para ver su ruta de orientación.',caseKey:null},
            {kicker:'CASO 1 · POSESIÓN DEL TERRENO',title:'Solicita orientación municipal',text:'¿Dónde ir? Municipalidad Provincial de Huancayo · Gerencia de Desarrollo Urbano.',requirements:['Solicitud dirigida al alcalde','DNI de los posesionarios','Plano de ubicación/localización','Memoria descriptiva','Declaración jurada notarial del solicitante','Declaración jurada notarial de 3 vecinos y exhibición de sus DNI','Presentar documentos en original'],steps:['Consulta el trámite en la Gerencia de Desarrollo Urbano','Prepara la solicitud y los documentos requeridos','Verifica las firmas profesionales y notariales necesarias','Presenta los documentos originales'],note:'Costo referencial del tríptico: S/ 412,60. Resultado: Certificado Municipal de Posesión. Confirma requisitos y tarifa vigentes.',caseKey:'posesion'},
            {kicker:'CASO 2 · ZONA EN FORMALIZACIÓN',title:'Consulta con COFOPRI',text:'¿Dónde ir? COFOPRI · Oficina Zonal Junín, Jr. Lima 590–594, Huancayo.',requirements:['Recibos de luz o agua','Arbitrios o impuesto predial','Contrato de compraventa','Escritura pública','Constancia de posesión','Otros documentos que acrediten ocupación'],steps:['Confirma si tu zona participa en el proceso de formalización','Participa del empadronamiento cuando corresponda','Espera la revisión de la información','El título se entrega si la zona cumple las condiciones'],note:'El tríptico indica que el proceso COFOPRI es gratuito. Si no tienes documentos, podrían considerarse declaraciones de vecinos.',caseKey:'cofopri'},
            {kicker:'CASO 3 · DOCUMENTOS SIN INSCRIPCIÓN',title:'Revisa la ruta en SUNARP',text:'¿Dónde ir? SUNARP · Oficina Registral Huancayo.',requirements:['Escritura pública u otro título de propiedad','Planos según el caso','En zonas no catastradas: planos firmados por verificador competente y visados por la municipalidad'],steps:['Revisa los documentos y planos de tu predio','Consulta los requisitos de inmatriculación en SUNARP','Presenta el título o parte notarial según corresponda'],note:'Costo registral referencial del tríptico: S/ 83,00. Si presentas parte notarial, normalmente lo presenta la notaría o su dependiente acreditado. Confirma la tarifa actual.',caseKey:'sunarp'},
            {kicker:'CASO 4 · HERENCIA O REPARTO FAMILIAR',title:'Organiza los documentos familiares',text:'Pueden intervenir notaría, SUNARP y SATH / Municipalidad, según corresponda.',requirements:['Partida de defunción','Declaratoria de herederos','Escritura pública o sentencia de división y partición'],steps:['Identifica los documentos familiares disponibles','Consulta con una notaría o SUNARP qué instrumento corresponde','Realiza la inscripción','Actualiza la información tributaria si aplica'],note:'No todo se resuelve en la Municipalidad. Confirma la ruta con la entidad correspondiente.',caseKey:'herencia'}
        ];
        const cases={
            posesion:{label:'Posesión del terreno',answer:'Si solo tienes posesión, la guía señala como primer paso consultar en la Municipalidad Provincial de Huancayo, Gerencia de Desarrollo Urbano. Como orientación, prepara solicitud dirigida al alcalde, DNI de los posesionarios, plano de ubicación, memoria descriptiva, declaraciones juradas y documentos originales. Los planos y la memoria pueden requerir firma de profesional habilitado y algunas declaraciones, firma notarial. El material menciona un costo referencial de S/ 412,60 para el certificado municipal de posesión; confirma el monto y los requisitos vigentes con la Municipalidad.'},
            cofopri:{label:'Zona en formalización COFOPRI',answer:'Si tu zona está en proceso de formalización, consulta con COFOPRI, Oficina Zonal Junín (Jr. Lima 590–594, Huancayo). Pueden servir recibos de luz o agua, arbitrios o impuesto predial, contrato de compraventa, escritura pública, constancia de posesión u otros documentos que acrediten ocupación. El tríptico indica que el trámite es gratuito dentro del proceso COFOPRI. La ruta puede incluir empadronamiento, revisión y entrega del título si la zona cumple las condiciones del proceso.'},
            sunarp:{label:'Inscripción en SUNARP',answer:'Si tienes documentos de propiedad pero el predio aún no figura en SUNARP, la guía orienta a consultar en la Oficina Registral de SUNARP. La documentación base puede incluir escritura pública u otro título de propiedad y planos según el caso; en zonas no catastradas, podrían requerirse planos firmados por profesional competente y visados por la municipalidad. El tríptico menciona S/ 83,00 como costo registral referencial. Si ya cuentas con parte notarial, normalmente lo presenta la notaría o su dependiente acreditado. Confirma los requisitos y la tarifa actual en SUNARP.'},
            herencia:{label:'Herencia o reparto familiar',answer:'Para una herencia o reparto familiar, pueden solicitar partida de defunción, declaratoria de herederos y escritura pública o sentencia de división y partición. La ruta puede involucrar notaría, SUNARP y SATH o la Municipalidad, según corresponda; después puede seguir la inscripción y la actualización tributaria. No todo se resuelve en la Municipalidad. Reúne la documentación familiar disponible y consulta primero con una notaría o con SUNARP para confirmar qué instrumento corresponde a tu caso.'}
        };
        let chatStarted=false;
        let brochureIndex=0;
        function toggleChat(force){chatPanel.classList.toggle('open',force===true?true:force===false?false:!chatPanel.classList.contains('open'));if(chatPanel.classList.contains('open')&&!chatStarted){chatStarted=true;botMessage('¡Hola! Te acompaño con el tríptico digital. Puedes pasar sus seis paneles o preguntarme por uno de los trámites.');showBrochure()}}
        function botMessage(text){const el=document.createElement('div');el.className='msg bot';el.textContent=text;log.appendChild(el);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight})}
        function userMessage(text){const el=document.createElement('div');el.className='msg user';el.textContent=text;log.appendChild(el);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight})}
        function showBrochure(index=brochureIndex){const oldPanel=panels[brochureIndex];if(oldPanel?.caseKey){const seconds=Math.min(1800,Math.round((Date.now()-lastPanelStart)/1000));track('case_view',oldPanel.caseKey,{},seconds)}brochureIndex=Math.max(0,Math.min(panels.length-1,index));lastPanelStart=Date.now();const p=panels[brochureIndex];const card=document.createElement('article');card.className='brochure-page';const head=document.createElement('div');head.className='brochure-kicker';head.textContent=p.kicker;card.appendChild(head);const title=document.createElement('h3');title.className='brochure-title';title.textContent=p.title;card.appendChild(title);const copy=document.createElement('p');copy.className='brochure-copy';copy.textContent=p.text;card.appendChild(copy);const note=document.createElement('div');note.className='brochure-note';note.textContent=p.note;card.appendChild(note);if(p.caseKey){track('case_view',p.caseKey);const req=document.createElement('details');req.className='brochure-section';const reqTitle=document.createElement('summary');reqTitle.textContent='Ver requisitos';req.appendChild(reqTitle);const reqList=document.createElement('ul');(p.requirements||[]).forEach(item=>{const li=document.createElement('li');li.textContent=item;reqList.appendChild(li)});req.appendChild(reqList);req.addEventListener('toggle',()=>{if(req.open)track('requirements_view',p.caseKey)});card.appendChild(req);const steps=document.createElement('details');steps.className='brochure-section';const stepsTitle=document.createElement('summary');stepsTitle.textContent='Ver pasos orientativos';steps.appendChild(stepsTitle);const stepList=document.createElement('ol');(p.steps||[]).forEach(item=>{const li=document.createElement('li');li.textContent=item;stepList.appendChild(li)});steps.appendChild(stepList);steps.addEventListener('toggle',()=>{if(steps.open)track('steps_view',p.caseKey)});card.appendChild(steps);const check=document.createElement('div');check.className='brochure-checklist';const checkTitle=document.createElement('strong');checkTitle.textContent='Mi lista para preparar';check.appendChild(checkTitle);const items=p.requirements||[];items.forEach(item=>{const label=document.createElement('label');const box=document.createElement('input');box.type='checkbox';box.addEventListener('change',()=>{if(!checklistStarted[p.caseKey]){checklistStarted[p.caseKey]=true;track('checklist_start',p.caseKey)}const done=check.querySelectorAll('input:checked').length;track('checklist_progress',p.caseKey,{checked:String(done),total:String(items.length)});if(done===items.length){track('checklist_complete',p.caseKey,{total:String(items.length)});showSatisfaction(p.caseKey)}});label.append(box,document.createTextNode(item));check.appendChild(label)});card.appendChild(check);const finish=document.createElement('button');finish.type='button';finish.className='brochure-ask';finish.textContent='Finalizar y responder encuesta';finish.onclick=()=>showSatisfaction(p.caseKey);card.appendChild(finish);const ask=document.createElement('button');ask.type='button';ask.className='brochure-ask';ask.textContent='Solicitar orientación';ask.onclick=()=>{track('help_click',p.caseKey);chooseCase(p.caseKey)};card.appendChild(ask)}const controls=document.createElement('div');controls.className='brochure-controls';const prev=document.createElement('button');prev.type='button';prev.className='brochure-arrow';prev.textContent='← Anterior';prev.disabled=brochureIndex===0;prev.onclick=()=>showBrochure(brochureIndex-1);const count=document.createElement('span');count.className='brochure-count';count.textContent=`${brochureIndex+1} / ${panels.length}`;const next=document.createElement('button');next.type='button';next.className='brochure-arrow';next.textContent='Siguiente →';next.disabled=brochureIndex===panels.length-1;next.onclick=()=>showBrochure(brochureIndex+1);controls.append(prev,count,next);card.appendChild(controls);const dots=document.createElement('div');dots.className='brochure-dots';panels.forEach((_,i)=>{const dot=document.createElement('button');dot.type='button';dot.className='brochure-dot'+(i===brochureIndex?' active':'');dot.setAttribute('aria-label',`Ir al panel ${i+1}`);dot.onclick=()=>showBrochure(i);dots.appendChild(dot)});card.appendChild(dots);log.appendChild(card);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight})}
        function showSatisfaction(caseKey){if(log.querySelector(`[data-survey="${caseKey}"]`))return;const form=document.createElement('form');form.className='satisfaction-survey';form.dataset.survey=caseKey;const profile=document.createElement('div');profile.className='satisfaction-profile';const nameLabel=document.createElement('label');nameLabel.textContent='Solo tu nombre';const nameInput=document.createElement('input');nameInput.type='text';nameInput.name='first_name';nameInput.autocomplete='given-name';nameInput.maxLength=60;nameInput.placeholder='Escribe tu nombre';nameInput.required=true;nameLabel.appendChild(nameInput);const ageLabel=document.createElement('label');ageLabel.textContent='Edad';const ageInput=document.createElement('input');ageInput.type='number';ageInput.name='age';ageInput.min='13';ageInput.max='120';ageInput.step='1';ageInput.placeholder='Tu edad';ageInput.required=true;ageLabel.appendChild(ageInput);const privacy=document.createElement('p');privacy.className='satisfaction-privacy';privacy.textContent='Se guardará tu nombre de pila y edad junto con tu calificación. No escribas apellidos.';profile.append(nameLabel,ageLabel,privacy);const title=document.createElement('strong');title.textContent='Encuesta de satisfacción';const question=document.createElement('p');question.textContent='¿Qué tan útil fue la información para ti?';const choices=document.createElement('div');choices.className='satisfaction-stars';choices.setAttribute('role','radiogroup');choices.setAttribute('aria-label','Califica la utilidad de la información, de 1 a 5 estrellas');for(let rating=1;rating<=5;rating++){const label=document.createElement('label');label.className='satisfaction-star';const input=document.createElement('input');input.type='radio';input.name='rating';input.value=String(rating);input.required=true;const star=document.createElement('span');star.textContent='★';star.setAttribute('aria-hidden','true');const accessible=document.createElement('span');accessible.className='sr-only';accessible.textContent=`${rating} ${rating===1?'estrella':'estrellas'}`;label.append(input,star,accessible);input.addEventListener('change',()=>{choices.querySelectorAll('.satisfaction-star').forEach((item,index)=>item.classList.toggle('selected',index<rating));submit.disabled=false});choices.appendChild(label)}const submit=document.createElement('button');submit.type='submit';submit.className='satisfaction-submit';submit.textContent='Enviar respuesta';submit.disabled=true;const status=document.createElement('div');status.className='satisfaction-status';status.setAttribute('role','status');form.append(title,profile,question,choices,submit,status);log.appendChild(form);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight});form.addEventListener('submit',async event=>{event.preventDefault();const selected=form.querySelector('input[name="rating"]:checked');if(!selected)return;submit.disabled=true;status.textContent='Enviando respuesta…';try{const response=await fetch('{{ route('analytics.satisfaction') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({session_key:sessionKey,case:caseKey,rating:Number(selected.value),first_name:nameInput.value.trim(),age:Number(ageInput.value)})});if(!response.ok)throw new Error('No se pudo guardar la respuesta. Intenta nuevamente.');form.replaceChildren();const thanks=document.createElement('p');thanks.className='satisfaction-thanks';thanks.textContent='¡Gracias! Tu respuesta fue registrada.';form.appendChild(thanks)}catch(error){status.textContent=error.message;submit.disabled=false}})}
        function advanceBrochure(){if(brochureIndex<panels.length-1)showBrochure(brochureIndex+1)}
        function showCases(){const box=document.createElement('div');box.className='chips';Object.entries(cases).forEach(([key,item])=>{const b=document.createElement('button');b.type='button';b.className='chip';b.textContent=item.label;b.onclick=()=>chooseCase(key);box.appendChild(b)});log.appendChild(box);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight})}
        function chooseCase(key,question=null){const item=cases[key];userMessage(question||item.label);track('case_select',key);botMessage(item.answer);showCases();const panel=panels.findIndex(p=>p.caseKey===key);if(panel>0&&brochureIndex!==panel)showBrochure(panel)}
        function selectCase(key){toggleChat(true);chooseCase(key)}
        function sendChat(event){event.preventDefault();const input=document.getElementById('chatInput');const value=input.value.trim();if(!value)return;input.value='';userMessage(value);const normalized=value.toLocaleLowerCase('es');const match=Object.entries(cases).find(([key,item])=>normalized.includes(key)||item.label.toLocaleLowerCase('es').split(' ').some(word=>word.length>5&&normalized.includes(word)));if(match){chooseCase(match[0],value)}else{botMessage('Puedo orientarte sobre estos cuatro casos. Elige el que más se acerca a tu situación y te indico pasos y entidad de referencia.');showCases()}}
        document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link)track('navigation_click',null,{target:link.getAttribute('href')})});
    </script>
</body>
</html>
